contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 nonOwnerKey) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);
        uint256 beforeBal = address(c).balance;

        bool reverted;
        address callerBefore = address(this);

        // First call from the test contract (which is the owner, since it deployed c).
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 afterOwnerBal = address(c).balance;

        // Second call attempt from a distinct non-owner address via a low-level call is not possible
        // with the allowed surface, so we assert the observable rule for the owner call: if it
        // succeeded, the balance must be zero; if it reverted, the balance must be unchanged.
        assert((reverted && afterOwnerBal == beforeBal) || (!reverted && afterOwnerBal == 0));
    }

    receive() external payable {}
}

