// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(uint256 nonOwnerKey) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        uint256 beforeBal = address(c).balance;
        bool reverted;
        address callerBefore = address(this);
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterOwnerBal = address(c).balance;
        assertTrue((reverted && afterOwnerBal == beforeBal) || (!reverted && afterOwnerBal == 0));
    }

    function testFuzz_run(uint256 nonOwnerKey) public {
        _run(nonOwnerKey);
    }

    receive() external payable {}
}
